/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { readMinor, mulDivMinor } from './work/lib/money.mjs';

const rows = JSON.parse(readFileSync('work/rows.json', 'utf8'));
const settlement = rows.map(({ id, unitMinor, quantity }) => {
  assert(Number.isSafeInteger(quantity), 'quantity must be an exact integer');
  const net = mulDivMinor(readMinor(unitMinor), BigInt(quantity), 1n, 'floor');
  return {
    id,
    net: { unit: 'EUR-cent', value: net.toString() },
    fee: {
      status: 'blocked',
      decisionRequired: 'Марине, владельцу расчётов, нужно утвердить правило расчёта сбора для отдела B, включая числитель и знаменатель ставки и режим округления (R-35).'
    }
  };
});

writeFileSync('settlement.json', JSON.stringify(settlement, null, 2) + '\\n', { flag: 'wx' });
NODE"

/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { readMinor } from './work/lib/money.mjs';

const readJson = path => JSON.parse(readFileSync(path, 'utf8'));
const input = readJson('work/rows.json');
const settlement = readJson('settlement.json');
assert.deepEqual(settlement.map(row => row.id), input.map(row => row.id));
assert.deepEqual(settlement.map(row => row.net), [
  { unit: 'EUR-cent', value: '153' },
  { unit: 'EUR-cent', value: '-30' }
]);
for (const row of settlement) {
  assert.equal(readMinor(row.net.value).toString(), row.net.value);
  assert.equal(row.fee.status, 'blocked');
  assert.deepEqual(Object.keys(row.fee), ['status', 'decisionRequired']);
  assert.match(row.fee.decisionRequired, /Марине.*числитель.*знаменатель.*округления.*R-35/);
}
console.log('Verified both row IDs, net DTOs, round trips, and fee decisions.');
NODE"

